'use strict';
const path = require('path');
const fs = require('fs-extra');
const axios = require('axios');
const cheerio = require('cheerio');
const { URL } = require('url');

const MAX_ASSETS  = 200;   // max number of assets to download
const TIMEOUT_MS  = 15000; // per-request timeout

/**
 * Download a site to a local directory for offline packaging.
 * Downloads HTML, linked CSS, JS, images and fonts.
 *
 * @param {string} siteUrl
 * @param {string} buildId  – used for tmp directory naming
 * @param {Function} onProgress
 * @returns {string} localDir
 */
async function downloadSite(siteUrl, buildId, onProgress) {
  const tmpDir = path.join(require('os').tmpdir(), `apkbuilder-${buildId}`);
  await fs.ensureDir(tmpDir);

  const baseUrl = new URL(siteUrl);
  const visited = new Set();
  let assetCount = 0;

  onProgress(`⬇️  Fetching: ${siteUrl}`);

  // Fetch the main HTML
  const html = await fetchText(siteUrl);
  await fs.writeFile(path.join(tmpDir, 'index.html'), rewriteHtml(html, baseUrl), 'utf8');
  onProgress('✅ HTML page downloaded');

  // Parse and collect assets
  const $ = cheerio.load(html);
  const assetUrls = new Set();

  // CSS <link>
  $('link[rel="stylesheet"]').each((_, el) => {
    const href = $(el).attr('href');
    if (href) assetUrls.add(resolveUrl(href, baseUrl));
  });

  // JS <script src>
  $('script[src]').each((_, el) => {
    const src = $(el).attr('src');
    if (src) assetUrls.add(resolveUrl(src, baseUrl));
  });

  // Images
  $('img[src]').each((_, el) => {
    const src = $(el).attr('src');
    if (src && !src.startsWith('data:')) assetUrls.add(resolveUrl(src, baseUrl));
  });

  // Inline style background images
  $('[style]').each((_, el) => {
    const style = $(el).attr('style') || '';
    const match = style.match(/url\(['"]?([^'")\s]+)['"]?\)/);
    if (match && !match[1].startsWith('data:')) assetUrls.add(resolveUrl(match[1], baseUrl));
  });

  // favicon
  $('link[rel~="icon"]').each((_, el) => {
    const href = $(el).attr('href');
    if (href) assetUrls.add(resolveUrl(href, baseUrl));
  });

  onProgress(`📎 Found ${assetUrls.size} assets to download`);

  for (const assetUrl of assetUrls) {
    if (assetCount >= MAX_ASSETS) {
      onProgress(`⚠️  Asset limit (${MAX_ASSETS}) reached, skipping remaining`);
      break;
    }
    if (visited.has(assetUrl)) continue;
    visited.add(assetUrl);

    try {
      const localPath = urlToLocalPath(assetUrl, tmpDir, baseUrl);
      await fs.ensureDir(path.dirname(localPath));

      const isText = /\.(css|js|svg|html?)$/i.test(assetUrl);
      if (isText) {
        const content = await fetchText(assetUrl);
        let processed = content;
        // If it's a CSS file, also download referenced resources
        if (assetUrl.endsWith('.css')) {
          const cssAssets = extractCssUrls(content, assetUrl);
          for (const cu of cssAssets) {
            if (assetCount < MAX_ASSETS && !visited.has(cu)) {
              assetUrls.add(cu);
            }
          }
          processed = rewriteCss(content, assetUrl, baseUrl);
        }
        await fs.writeFile(localPath, processed, 'utf8');
      } else {
        const buffer = await fetchBinary(assetUrl);
        await fs.writeFile(localPath, buffer);
      }
      assetCount++;
    } catch (e) {
      onProgress(`⚠️  Could not download: ${assetUrl.split('/').pop()}`);
    }
  }

  onProgress(`✅ Downloaded ${assetCount} assets`);
  return tmpDir;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function resolveUrl(href, base) {
  try {
    return new URL(href, base).href;
  } catch (_) {
    return null;
  }
}

function urlToLocalPath(assetUrl, tmpDir, base) {
  try {
    const u = new URL(assetUrl);
    // Same origin → local path
    let rel = u.pathname.replace(/^\//, '');
    if (!rel || rel.endsWith('/')) rel = rel + 'index.html';
    // Sanitize
    rel = rel.replace(/[?#].*$/, '').replace(/\.\./g, '_');
    return path.join(tmpDir, rel.split('/').join(path.sep));
  } catch (_) {
    return path.join(tmpDir, 'assets', sanitizeFilename(assetUrl));
  }
}

function sanitizeFilename(url) {
  return url.replace(/[^a-zA-Z0-9._-]/g, '_').slice(-100);
}

function rewriteHtml(html, base) {
  // Replace absolute URLs pointing to the same origin with relative paths
  const origin = base.origin;
  return html
    .replace(new RegExp(`(href|src|action)=["']${escapeRegex(origin)}(/[^"']*)?["']`, 'gi'),
      (_, attr, p) => `${attr}=".${p || '/'}"`);
}

function rewriteCss(css, cssUrl, base) {
  // Rewrite url(...) in CSS to relative paths
  return css.replace(/url\(['"]?([^'")\s]+)['"]?\)/gi, (match, href) => {
    if (href.startsWith('data:') || href.startsWith('#')) return match;
    const abs = resolveUrl(href, cssUrl);
    if (!abs) return match;
    try {
      const u = new URL(abs);
      const rel = u.pathname.replace(/^\//, '');
      return `url("/${rel}")`;
    } catch (_) {
      return match;
    }
  });
}

function extractCssUrls(css, cssUrl) {
  const urls = [];
  const regex = /url\(['"]?([^'")\s]+)['"]?\)/gi;
  let m;
  while ((m = regex.exec(css)) !== null) {
    const href = m[1];
    if (!href.startsWith('data:') && !href.startsWith('#')) {
      const abs = resolveUrl(href, cssUrl);
      if (abs) urls.push(abs);
    }
  }
  return urls;
}

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

async function fetchText(url) {
  const resp = await axios.get(url, {
    timeout: TIMEOUT_MS,
    responseType: 'text',
    maxContentLength: 10 * 1024 * 1024,
    headers: { 'User-Agent': 'Mozilla/5.0 (APK-Builder/1.0)' }
  });
  return resp.data;
}

async function fetchBinary(url) {
  const resp = await axios.get(url, {
    timeout: TIMEOUT_MS,
    responseType: 'arraybuffer',
    maxContentLength: 20 * 1024 * 1024,
    headers: { 'User-Agent': 'Mozilla/5.0 (APK-Builder/1.0)' }
  });
  return Buffer.from(resp.data);
}

module.exports = { downloadSite };
